import { useState } from "react";
import "./styles/UserInfo.css";
import 'bootstrap-icons/font/bootstrap-icons.css';

function UserInfo({ user, onBack, onLogout, onViewInfo }) {
  const [showUserMenu, setShowUserMenu] = useState(false);

  return (
    <div className="userinfo-container">
      <header className="superadmin-header"> {/* mismo estilo que AdminS */}
        <h1 className="superadmin-title">TalkinPon</h1>
        <div className="superadmin-user-menu-wrapper">
          <button className="superadmin-user-btn" onClick={() => setShowUserMenu(!showUserMenu)}>
            <i className="bi bi-person-circle"></i>
          </button>
          {showUserMenu && (
            <div className="superadmin-user-dropdown">
              <button
                className="superadmin-dropdown-item"
                onClick={() => {
                  onViewInfo?.();
                  setShowUserMenu(false);
                }}
              >
                Ver información
              </button>
              {onBack && (
                <button
                  className="superadmin-dropdown-item"
                  onClick={() => {
                    onBack();
                    setShowUserMenu(false);
                  }}
                >
                  Volver
                </button>
              )}
              <button
                className="superadmin-dropdown-item superadmin-logout"
                onClick={() => {
                  onLogout();
                  setShowUserMenu(false);
                }}
              >
                Cerrar sesión
              </button>
            </div>
          )}
        </div>
      </header>

      <main className="superadmin-main">
        <div className="superadmin-dashboard-container">
          <div className="superadmin-welcome-section">
            <h2>Información de {user.username}</h2>
            <p>Detalles y datos asociados al usuario.</p>
          </div>

          <div className="superadmin-modules-grid">
            <div className="superadmin-module-card superadmin-transparent">
              <h3>Usuario</h3>
              <p>Nombre: {user.name}</p>
              <p>Rol: {user.role}</p>
              <p>Email: {user.email}</p>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}

export default UserInfo;
